static void audio_playback_play_fallback(audio_playback_t* pb)
{
    FILE* nxplayer;
    int status;
    uint64_t duration_ms;
    uint64_t bytes_per_second;
    unsigned int volume;

    if (!pb->fallback_file) {
        return;
    }

    fclose(pb->fallback_file);
    pb->fallback_file = NULL;

    if (pb->stopped || pb->total_written == 0) {
        remove(PB_FALLBACK_PATH);
        return;
    }

    nxplayer = popen("nxplayer", "w");
    if (!nxplayer) {
        syslog(LOG_ERR, "[%s] nxplayer launch failed: %d\n", TAG, errno);
        remove(PB_FALLBACK_PATH);
        return;
    }

    volume = audio_playback_load_volume();
    fprintf(nxplayer, "volume %u\n", volume);
    fflush(nxplayer);

    fprintf(nxplayer, "playraw %s %u %u %u 0\n",
        PB_FALLBACK_PATH, pb->channels, pb->bits_per_sample, pb->sample_rate);
    fflush(nxplayer);

    bytes_per_second = (uint64_t)pb->sample_rate * pb->bytes_per_frame;
    duration_ms = bytes_per_second == 0 ? 0 :
        ((uint64_t)pb->total_written * 1000 + bytes_per_second - 1) /
        bytes_per_second;
    syslog(LOG_INFO, "[%s] nxplayer fallback playback: %llums\n",
        TAG, (unsigned long long)duration_ms);
    usleep((useconds_t)((duration_ms + 250) * 1000));

    fprintf(nxplayer, "q\n");
    fflush(nxplayer);
    status = pclose(nxplayer);
    syslog(status == 0 ? LOG_INFO : LOG_ERR,
        "[%s] nxplayer fallback finished: status=%d bytes=%zu\n",
        TAG, status, pb->total_written);
    remove(PB_FALLBACK_PATH);
}

